UPDATE `quest_template` SET `LogTitle`='Aréna mestere', `LogDescription`='Beszélj Short John Mithrillel a Stranglethorn Arénában.', `QuestDescription`='Ennél többnek kell lennie ahhoz, hogy valaki az aréna mestere legyen! Talán a kalóz, aki az eseményt vezeti Gurubashiban, tudja!', `QuestCompletionLog`='Jelentkezz Short John Mithrilnél, a Gurubashi Arénában, Stranglethorn Vale-ben.' WHERE `ID`=7810;
