UPDATE `quest_template` SET `LogTitle`='Egy bajnok felemelkedik', `LogDescription`='Beszélj Justicar Mariel Trueheart-tal, az Argent Tournament Groundsnál.', `QuestDescription`='Gratulálok. Számos harci formát elsajátítottál, és minden kihívást legyőztél, amivel szembekerültél. Kétségtelen, hogy készen állsz megmérkőzni a tornán összegyűlt legjobb harcosokkal, a fővárosok bajnokaival szemben.Justicar Mariel Trueheart szeretne beszélni veled, és hivatalosan is beírni téged a bajnokok nagy viadalára.', `QuestCompletionLog`=NULL WHERE `ID`=13732;
