UPDATE `quest_template` SET `LogTitle`='Egy bajnok felemelkedik', `LogDescription`='Beszélj Justicar Mariel Trueheart-tal, az Argent Tournament Groundsnál.', `QuestDescription`='Kiérdemelted a tiszteletemet és társaid tiszteletét. Legyőztél mindenkit, aki kihívott, és elsajátítottad a tornaharc módjait. Nincs kétségem afelől, hogy készen állsz szembenézni más városok bajnokaival Orgrimmar dicsőségéért!Justicar Mariel Trueheart szeretne beszélni veled, és hivatalosan is beírni téged a bajnokok nagy viadalára.', `QuestCompletionLog`=NULL WHERE `ID`=13736;
