UPDATE `quest_template` SET `LogTitle`='Ajándék Ironforge urának', `LogDescription`='Ajándékozd oda a Lovely Charm Braceletet King Magni Bronzebeardnek, Ironforge-ban.', `QuestDescription`='Szeretnél egy Lovely Charm Braceletet készíteni Ironforge urának? Biztosan lelkes lenne.Már van egy Lovely Charm Collector''s Kitted?', `QuestCompletionLog`='Térj vissza King Magni Bronzebeardhez, Dun Morogh-ban.' WHERE `ID`=24609;
