UPDATE `quest_template` SET `LogTitle`='A Pit of Saron', `LogDescription`='Találkozz Lady Sylvanas Windrunnerrel a Pit of Saron bejáratánál.', `QuestDescription`='Gyorsan, a portálon át! A túloldalon megtalállak.' WHERE `ID`=24682;
