UPDATE `quest_template` SET `LogTitle`='Személyes tulajdon', `LogDescription`='Vidd el a Sealed Chestet Highlord Darion Mograine-nek, az Icecrown Citadelbe.', `QuestDescription`='Nem találsz sem zsanért, sem nyílást ezen a dobozon. Ha nem hallanád a tárgyak elmozdulását bent, könnyen összetéveszthetnéd egy tömör fémdarabbal.Ha bárki ismerheti a kinyitásának módját, az Highlord Mograine.' WHERE `ID`=24914;
UPDATE `quest_template` SET `LogTitle`='Mograine újraegyesülése' WHERE `ID`=24915;
